sections.mermaid_mindmap:
flowchart TD
    A[Plano de Contas] --> B["Objetivo: Uniformizar<br/>Registros"]
    A --> C["Conteúdo: Todas as Contas"]
    A --> D["Característica: Não<br/>Universal"]

    D --> D1["Elaborado por<br/>cada<br/>entidade"]
    D --> D2[Conforme<br/>peculiaridades]
