    classDef readableRoot fill:#EDE9FE,stroke:#6D28D9,stroke-width:2.4px,color:#111827;
    classDef readableItem fill:#FFFFFF,stroke:#A78BFA,stroke-width:1.4px,color:#111827;
    classDef readableImportant fill:#FEF3C7,stroke:#D97706,stroke-width:2px,color:#111827;
    classDef readableCritical fill:#FEE2E2,stroke:#DC2626,stroke-width:2.2px,color:#111827;
    classDef readableProcess fill:#E0F2FE,stroke:#0284C7,stroke-width:1.8px,color:#111827;
